mapper.select:
SELECT id, biz_id, from_user_id, target_user_id, visit_count,
       first_visited_at, last_visited_at, created_at, updated_at, deleted
FROM match_center.profile_visit
WHERE target_user_id = #{targetUserId}
  AND deleted = 0

    AND (last_visited_at < #{cursorLastVisitedAt}
         OR (last_visited_at = #{cursorLastVisitedAt} AND biz_id < #{cursorBizId}))

ORDER BY last_visited_at DESC, biz_id DESC
LIMIT #{pageSize}
